<script>
 import {onMount} from 'svelte';import {createQuickSelection} from '../coverflow-selection';
 import {layout,coverflowMax,saveLayout} from '../layout.svelte';import ResizeHandle from './ResizeHandle.svelte';
 import {ChevronLeft,ChevronRight,Check,FolderOpen,Minus,SquareCheck,ChevronDown,ChevronUp} from 'lucide-svelte';
 import {studio,assets,current,select,toggle} from '../studio.svelte';
 let list=$derived(assets());let index=$derived(Math.max(0,list.findIndex(a=>a.id===studio.aid)));let accumulator=0;let hovered=false,root,spaceHeld=$state(false),selecting=$state(true),badgeVisible=$state(false),badgeSelecting=$state(true),badgeEpoch=$state(0);let badgeTimer;
 function modeNotice(value,checked){spaceHeld=value;selecting=checked;clearTimeout(badgeTimer);if(value){badgeSelecting=checked;badgeVisible=true;badgeEpoch++;}else if(badgeVisible)badgeTimer=setTimeout(()=>badgeVisible=false,600);}
 const quick=createQuickSelection({getIds:()=>list.map(a=>a.id),getCurrent:()=>studio.aid,isSelected:id=>studio.selected.includes(id),setSelected:(ids,checked)=>{studio.selected=checked?[...new Set([...studio.selected,...ids])]:studio.selected.filter(id=>!ids.includes(id));studio.batchScope='auto';},navigate:select,onHeld:modeNotice});
 function typing(){const el=document.activeElement;return !!el&&(el.isContentEditable||!!el.closest('input,textarea,select,[role=textbox]'));}
 function available(){return hovered&&!typing()&&!studio.busy&&!studio.modal&&!studio.confirm&&!layout.coverflowCollapsed&&studio.mode==='edit'&&studio.view==='canvas';}
 function release(){quick.release();accumulator=0;}
 function keyDown(e){if(e.code==='Escape'){release();return;}if(e.code!=='Space'||e.ctrlKey||e.altKey||e.metaKey||e.isComposing||!available())return;e.preventDefault();e.stopPropagation();if(!e.repeat)quick.press();}
 function keyUp(e){if(e.code!=='Space'||!quick.held)return;e.preventDefault();e.stopPropagation();release();}
 onMount(()=>{window.addEventListener('keydown',keyDown,true);window.addEventListener('keyup',keyUp,true);window.addEventListener('blur',release);const hide=()=>{if(document.hidden)release();};document.addEventListener('visibilitychange',hide);return()=>{window.removeEventListener('keydown',keyDown,true);window.removeEventListener('keyup',keyUp,true);window.removeEventListener('blur',release);document.removeEventListener('visibilitychange',hide);release();clearTimeout(badgeTimer);};});
 $effect(()=>{studio.pid;if(studio.busy||studio.modal||studio.confirm||layout.coverflowCollapsed)release();});let selectedCount=$derived(list.filter(a=>studio.selected.includes(a.id)).length);let allSelected=$derived(list.length>0&&selectedCount===list.length);
 function selectAll(){if(studio.busy)return;const ids=list.map(a=>a.id);studio.selected=allSelected?studio.selected.filter(id=>!ids.includes(id)):[...new Set([...studio.selected,...ids])];studio.batchScope='auto';}
 function previous(){if(index>0)select(list[index-1].id);}function next(){if(index<list.length-1)select(list[index+1].id);}
 function wheel(e){if(studio.busy||studio.modal||studio.confirm||layout.coverflowCollapsed){release();return;}e.preventDefault();const delta=e.deltaY||e.deltaX;if(quick.held){if(!available()){release();return;}quick.wheel(delta*(e.deltaMode===1?16:e.deltaMode===2?240:1));return;}accumulator+=delta;if(accumulator>35){next();accumulator=0;}else if(accumulator< -35){previous();accumulator=0;}}
 // Exact GVPAK STUDIO 2 geometry and timing, reimplemented as a Svelte component.
 function position(offset){const a=Math.abs(offset);const x=offset===0?0:Math.sign(offset)*(130+(a-1)*75);const y=offset===0?0:offset<0?44:-44;return `transform:translateX(${x}px) translateZ(${offset===0?60:-a*40}px) rotateY(${y}deg) scale(${offset===0?1.06:Math.max(.68,.95-a*.06)});--cf-wash:${Math.min(.7,a*.14)};z-index:${100-a};`;}
</script>
<section bind:this={root} class="cf-root" class:quick-selecting={spaceHeld} onpointerenter={e=>{hovered=e.pointerType!=='touch';}} onpointerleave={()=>{hovered=false;release();}} onpointercancel={()=>{hovered=false;release();}} class:collapsed={layout.coverflowCollapsed} aria-label="Coverflow" title="Space: toggle current image · Hold Space + scroll: select or deselect images" style:--cf-height={`${Math.min(layout.coverflowHeight,coverflowMax())}px`} onwheel={wheel}>
 <ResizeHandle axis="height" bind:value={layout.coverflowHeight} min={100} max={coverflowMax()} label="Coverflow height" onstart={()=>layout.coverflowCollapsed=false} onfinish={saveLayout} reset={()=>{layout.coverflowHeight=144;layout.coverflowCollapsed=false;}}/>
 <div class="cf-header"><button class="cf-project" onclick={()=>studio.view='projects'}><FolderOpen size={13}/>{current()?.name||'Projects'}</button><span class="cf-header-actions"><button class="cf-collapse" aria-label={layout.coverflowCollapsed?'Expand Coverflow':'Collapse Coverflow'} aria-expanded={!layout.coverflowCollapsed} title={layout.coverflowCollapsed?'Expand Coverflow':'Collapse Coverflow'} onclick={()=>{layout.coverflowCollapsed=!layout.coverflowCollapsed;saveLayout();}}>{#if layout.coverflowCollapsed}<ChevronUp size={14}/>{:else}<ChevronDown size={14}/>{/if}</button><button class="cf-select-all" class:active={allSelected} role="checkbox" aria-checked={allSelected?true:selectedCount>0?'mixed':false} aria-label={allSelected?'Deselect all images':'Select all images'} title={allSelected?'Deselect all':selectedCount?'Select remaining images':'Select all'} disabled={!list.length||!!studio.busy} onclick={selectAll}>{#if allSelected}<SquareCheck size={13}/>{:else if selectedCount}<Minus size={13}/>{:else}<span class="select-all-square"></span>{/if}All</button>{list.length} images{#if studio.selected.length}<b>{studio.selected.length} selected</b>{/if}</span></div>
 <div class="cf-stage"><button class="cf-arrow cf-prev" disabled={index<=0} onclick={previous} aria-label="Previous image"><ChevronLeft size={18}/></button><div class="cf-stack">{#each list as a,i (a.id)}{#if Math.abs(i-index)<=7}<div class:cf-current={i===index} class="cf-card" data-side={i>index?'right':i<index?'left':'center'} style={position(i-index)} role="group" aria-label={a.name}><button class="cf-image-button" onclick={()=>select(a.id)} aria-label={`Select ${a.name}`}><img src={studio.thumbs[a.id]} alt={a.name}/></button><button class="cf-check" class:checked={studio.selected.includes(a.id)} onclick={()=>toggle(a.id)} aria-label={`Include ${a.name}`} aria-pressed={studio.selected.includes(a.id)}>{#if studio.selected.includes(a.id)}<Check size={11}/>{/if}</button><span class="cf-caption">{a.name}</span></div>{/if}{/each}</div><button class="cf-arrow cf-next" disabled={index>=list.length-1} onclick={next} aria-label="Next image"><ChevronRight size={18}/></button></div>
 <div class="cf-footer">{#key badgeEpoch}{#if badgeVisible}<span class="cf-mode-chip" class:removing={!badgeSelecting} class:released={!spaceHeld} role="status" aria-live="polite">{#if badgeSelecting}<Check size={12}/>{:else}<Minus size={12}/>{/if}{badgeSelecting?'Select':'Deselect'}</span>{/if}{/key}<button onclick={previous} disabled={index<=0} aria-label="Previous cover"><ChevronLeft size={12}/></button><span><b>{String(list.length?index+1:0).padStart(3,'0')}</b><i>/</i>{String(list.length).padStart(3,'0')}</span><button onclick={next} disabled={index>=list.length-1} aria-label="Next cover"><ChevronRight size={12}/></button></div>
</section>
